//! noevia#1318: native read-only `GET /api/v1/models/detail` through the real router.
//!
//! On Linux every case of `fixtures/model-detail-python.v1.json` (the actual services Python,
//! regenerated by CI from the pinned ref) runs through the router and the kernel-contained
//! opener, with a stand-in for the Python child that answers the private runtime call with the
//! body the real child rendered for that case. Elsewhere that opener refuses by design, which the
//! refusal test asserts; the lib tests run the same cases on every platform.
#![cfg(feature = "native-model-detail")]
#![allow(
    clippy::unwrap_used,
    clippy::expect_used,
    clippy::panic,
    clippy::indexing_slicing
)]
use axum::{body::Body, http::Request};
use http_body_util::BodyExt;
use noevia_model_manager::{model_detail::ModelDetail, Container, DockerRead, Redactor, StateData};
use std::{future::Future, path::Path, pin::Pin, sync::Arc};
use tower::ServiceExt;

const TOKEN: &str = "synthetic-model-loader-token-0123456789abcdef";
const PATH: &str = "/api/v1/models/detail";
const RUNTIME: &str = "/api/v1/internal/model-detail-runtime";
const REFUSED: &[u8] = br#"{"detail":"Native model detail is unavailable"}"#;
/// A GGUF v3 header with one key: general.architecture = "llama".
const LLAMA: &str =
    "474755460300000000000000000000000100000000000000140000000000000067656e6572616c2e6172636869746563747572650800000005000000000000006c6c616d61";

type Job<'a, T> = Pin<Box<dyn Future<Output = Result<T, &'static str>> + Send + 'a>>;
struct NoDocker;
impl DockerRead for NoDocker {
    fn containers(&self) -> Job<'_, Vec<Container>> {
        Box::pin(async { Err("not used") })
    }
    fn logs<'a>(&'a self, _: &'a str, _: usize) -> Job<'a, Vec<u8>> {
        Box::pin(async { Err("not used") })
    }
}

/// `roots` is (models, ini); `None` is the default python selector.
fn state(roots: Option<(&Path, &Path)>, legacy_base: &str) -> Arc<StateData> {
    Arc::new(StateData {
        #[cfg(feature = "native-diagnose")]
        diagnosis: None,
        #[cfg(feature = "native-prompts")]
        prompts: None,
        #[cfg(feature = "native-settings")]
        settings: None,
        model_updates: None,
        model_detail: roots.map(|(models, ini)| Arc::new(ModelDetail::new(models, ini))),
        sections: None,
        embedding: None,
        host: None,
        token: TOKEN.into(),
        configured: vec![],
        docker: Arc::new(NoDocker),
        redactor: Redactor::new().unwrap(),
        permits: tokio::sync::Semaphore::new(4),
        legacy: noevia_model_manager::legacy_client().unwrap(),
        legacy_base: legacy_base.into(),
        idle_unload: None,
        #[cfg(feature = "native-download-targets")]
        download_targets: None,
        #[cfg(feature = "native-badges")]
        badges: None,
    })
}

struct Answer {
    status: u16,
    content_type: Option<String>,
    body: Vec<u8>,
}

async fn send(state: Arc<StateData>, method: &str, path: &str, token: bool) -> Answer {
    let mut request = Request::builder().method(method).uri(path);
    if token {
        request = request.header("x-model-loader-token", TOKEN);
    }
    let response = noevia_model_manager::router(state)
        .oneshot(request.body(Body::empty()).unwrap())
        .await
        .unwrap();
    Answer {
        status: response.status().as_u16(),
        content_type: response
            .headers()
            .get("content-type")
            .map(|v| v.to_str().unwrap().to_owned()),
        body: response
            .into_body()
            .collect()
            .await
            .unwrap()
            .to_bytes()
            .to_vec(),
    }
}

/// A one-shot stand-in for the Python child: records the request head and answers `body` with
/// `status`. Returns (base URL, request head).
async fn child(status: u16, body: String) -> (String, tokio::task::JoinHandle<String>) {
    use tokio::io::{AsyncReadExt, AsyncWriteExt};
    let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
    let base = format!("http://{}", listener.local_addr().unwrap());
    let task = tokio::spawn(async move {
        let (mut socket, _) = listener.accept().await.unwrap();
        let mut seen = Vec::new();
        let mut buf = [0u8; 4096];
        while !seen.windows(4).any(|w| w == b"\r\n\r\n") {
            let n = socket.read(&mut buf).await.unwrap();
            assert!(n > 0);
            seen.extend_from_slice(&buf[..n]);
        }
        let head = format!(
            "HTTP/1.1 {status} X\r\ncontent-type: application/json\r\ncontent-length: {}\r\nconnection: close\r\n\r\n",
            body.len()
        );
        socket.write_all(head.as_bytes()).await.unwrap();
        socket.write_all(body.as_bytes()).await.unwrap();
        String::from_utf8_lossy(&seen).into_owned()
    });
    (base, task)
}

fn hex(text: &str) -> Vec<u8> {
    (0..text.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&text[i..i + 2], 16).unwrap())
        .collect()
}

/// One model file `a.gguf` with an architecture, under `root/models`.
fn folder(root: &Path) -> std::path::PathBuf {
    let models = root.join("models");
    std::fs::create_dir_all(&models).unwrap();
    std::fs::write(models.join("a.gguf"), hex(LLAMA)).unwrap();
    models
}

#[tokio::test]
async fn python_mode_forwards_get_unchanged() {
    let (base, seen) = child(200, r#"{"legacy":true}"#.into()).await;
    let answer = send(
        state(None, &base),
        "GET",
        "/api/v1/models/detail?key=a.gguf",
        true,
    )
    .await;
    assert_eq!(answer.body, br#"{"legacy":true}"#);
    assert!(seen
        .await
        .unwrap()
        .starts_with("GET /api/v1/models/detail?key=a.gguf HTTP/1.1\r\n"));
}

#[tokio::test]
async fn the_private_runtime_call_is_never_reachable_from_outside() {
    let dir = tempfile::tempdir().unwrap();
    let models = folder(dir.path());
    let ini = models.join("models.ini");
    for roots in [None, Some((models.as_path(), ini.as_path()))] {
        let answer = send(
            state(roots, "http://127.0.0.1:9"),
            "GET",
            &format!("{RUNTIME}?bytes=1&fit=1"),
            true,
        )
        .await;
        assert_eq!(answer.status, 404);
        assert_eq!(answer.body, br#"{"detail":"Not Found"}"#);
    }
}

#[tokio::test]
async fn native_route_keeps_auth_and_non_get_policy() {
    let dir = tempfile::tempdir().unwrap();
    let models = folder(dir.path());
    let ini = models.join("models.ini");
    let make = || state(Some((&models, &ini)), "http://127.0.0.1:9");
    let unauthorized = send(make(), "GET", "/api/v1/models/detail?key=a.gguf", false).await;
    assert_eq!(unauthorized.status, 401);
    assert_eq!(unauthorized.body, br#"{"error":"unauthorized"}"#);
    for method in ["POST", "PUT", "DELETE", "HEAD"] {
        let answer = send(make(), method, "/api/v1/models/detail?key=a.gguf", true).await;
        assert_eq!(answer.status, 405, "{method}");
    }
    let slash = send(make(), "GET", "/api/v1/models/detail/?key=a.gguf", true).await;
    assert_eq!(slash.status, 404);
    // Answered before any file is read, on every platform.
    let missing = send(make(), "GET", PATH, true).await;
    assert_eq!(missing.status, 422);
    assert_eq!(missing.content_type.as_deref(), Some("application/json"));
    assert_eq!(
        missing.body,
        br#"{"detail":[{"type":"missing","loc":["query","key"],"msg":"Field required","input":null}]}"#
    );
    let bad = send(make(), "GET", "/api/v1/models/detail?key=../a.gguf", true).await;
    assert_eq!(bad.status, 400);
    assert_eq!(bad.body, br#"{"detail":"bad model key"}"#);
}

#[cfg(not(target_os = "linux"))]
#[tokio::test]
async fn without_the_contained_opener_the_route_refuses() {
    let dir = tempfile::tempdir().unwrap();
    let models = folder(dir.path());
    let answer = send(
        state(
            Some((&models, &models.join("models.ini"))),
            "http://127.0.0.1:9",
        ),
        "GET",
        "/api/v1/models/detail?key=a.gguf",
        true,
    )
    .await;
    assert_eq!(answer.status, 503);
    assert_eq!(answer.body, REFUSED);
}

#[cfg(target_os = "linux")]
mod linux {
    use super::*;
    use serde_json::Value;

    const UNAVAILABLE: &[u8] = br#"{"detail":"Python-owned endpoint unavailable"}"#;

    fn fixture() -> Value {
        serde_json::from_str(include_str!("fixtures/model-detail-python.v1.json")).unwrap()
    }

    fn time(ns: i128) -> std::time::SystemTime {
        let magnitude = std::time::Duration::from_nanos(u64::try_from(ns.unsigned_abs()).unwrap());
        if ns >= 0 {
            std::time::UNIX_EPOCH + magnitude
        } else {
            std::time::UNIX_EPOCH - magnitude
        }
    }

    /// Builds one case like the generator does; returns (models, ini).
    fn build(root: &Path, case: &Value) -> (std::path::PathBuf, std::path::PathBuf) {
        let models = root.join("models");
        let ini = models.join("models.ini");
        for name in case["outside"].as_array().into_iter().flatten() {
            std::fs::write(root.join(name.as_str().unwrap()), b"GGUF").unwrap();
        }
        match case["models"].as_str().unwrap_or("dir") {
            "missing" => {}
            "file" => std::fs::write(&models, b"").unwrap(),
            kind => {
                if kind == "link" {
                    let real = root.join("real-models");
                    std::fs::create_dir(&real).unwrap();
                    std::os::unix::fs::symlink(&real, &models).unwrap();
                } else {
                    std::fs::create_dir(&models).unwrap();
                }
                for dir in case["dirs"].as_array().into_iter().flatten() {
                    std::fs::create_dir_all(models.join(dir.as_str().unwrap())).unwrap();
                }
                let files = case["files"].as_array().cloned().unwrap_or_default();
                for file in &files {
                    let path = models.join(file["name"].as_str().unwrap());
                    std::fs::create_dir_all(path.parent().unwrap()).unwrap();
                    std::fs::write(&path, hex(file["hex"].as_str().unwrap())).unwrap();
                    if let Some(size) = file["size"].as_u64() {
                        std::fs::File::options()
                            .write(true)
                            .open(&path)
                            .unwrap()
                            .set_len(size)
                            .unwrap();
                    }
                }
                for link in case["links"].as_array().into_iter().flatten() {
                    std::os::unix::fs::symlink(
                        link[1].as_str().unwrap(),
                        models.join(link[0].as_str().unwrap()),
                    )
                    .unwrap();
                }
                for link in case["abslinks"].as_array().into_iter().flatten() {
                    let target = std::fs::canonicalize(&models)
                        .unwrap()
                        .join(link[1].as_str().unwrap());
                    std::os::unix::fs::symlink(target, models.join(link[0].as_str().unwrap()))
                        .unwrap();
                }
                match &case["ini"] {
                    Value::Null => {}
                    Value::String(s) if s == "dir" => std::fs::create_dir(&ini).unwrap(),
                    Value::Object(o) => {
                        let bytes = match o.get("text") {
                            Some(text) => text.as_str().unwrap().as_bytes().to_vec(),
                            None => hex(o["hex"].as_str().unwrap()),
                        };
                        std::fs::write(&ini, bytes).unwrap();
                    }
                    other => panic!("unknown ini {other}"),
                }
                for file in &files {
                    let ns = file["mtime"]
                        .as_i64()
                        .map(i128::from)
                        .or_else(|| file["mtime"].as_u64().map(i128::from))
                        .unwrap();
                    let t = time(ns);
                    std::fs::File::options()
                        .write(true)
                        .open(models.join(file["name"].as_str().unwrap()))
                        .unwrap()
                        .set_times(std::fs::FileTimes::new().set_accessed(t).set_modified(t))
                        .unwrap();
                }
            }
        }
        (models, ini)
    }

    #[tokio::test]
    async fn every_case_matches_the_actual_python_route_through_the_router() {
        let fixture = fixture();
        let mut checked = 0;
        for case in fixture["cases"].as_array().unwrap() {
            let tmp = tempfile::tempdir().unwrap();
            let (models, ini) = build(tmp.path(), case);
            let prefix = serde_json::to_string(models.to_str().unwrap()).unwrap();
            let prefix = prefix[1..prefix.len() - 1].to_owned();
            for result in case["results"].as_array().unwrap() {
                let query = result["query"].as_str().unwrap();
                let uri = if query.is_empty() {
                    PATH.to_owned()
                } else {
                    format!("{PATH}?{query}")
                };
                let runtime = &result["runtime"];
                let (base, seen) = if runtime.is_null() {
                    ("http://127.0.0.1:9".to_owned(), None)
                } else {
                    let (base, seen) = child(200, runtime["body"].as_str().unwrap().into()).await;
                    (base, Some(seen))
                };
                let answer = send(state(Some((&models, &ini)), &base), "GET", &uri, true).await;
                let body = String::from_utf8(answer.body)
                    .unwrap()
                    .replace(&prefix, "@MODELS@");
                assert_eq!(
                    (answer.status, body.as_str()),
                    (
                        u16::try_from(result["status"].as_u64().unwrap()).unwrap(),
                        result["body"].as_str().unwrap()
                    ),
                    "case {} query {query}",
                    case["id"]
                );
                assert_eq!(
                    answer.content_type.as_deref(),
                    result["content_type"].as_str(),
                    "case {} query {query}",
                    case["id"]
                );
                if let Some(seen) = seen {
                    let head = seen.await.unwrap();
                    let fit = if runtime["fit"].as_bool().unwrap() {
                        1
                    } else {
                        0
                    };
                    assert!(
                        head.starts_with(&format!(
                            "GET {RUNTIME}?bytes={}&fit={fit} HTTP/1.1\r\n",
                            runtime["bytes"]
                        )),
                        "{head}"
                    );
                    assert!(
                        head.to_ascii_lowercase()
                            .contains(&format!("x-model-loader-token: {TOKEN}\r\n")),
                        "{head}"
                    );
                }
                checked += 1;
            }
        }
        assert!(checked >= 86, "{checked}");
    }

    #[tokio::test]
    async fn a_child_that_cannot_answer_is_never_guessed_around() {
        let dir = tempfile::tempdir().unwrap();
        let models = folder(dir.path());
        let ini = models.join("models.ini");
        let uri = "/api/v1/models/detail?key=a.gguf";
        // The child's own unhandled error is Python's 500.
        let (base, _seen) = child(500, "Internal Server Error".into()).await;
        let failed = send(state(Some((&models, &ini)), &base), "GET", uri, true).await;
        assert_eq!(failed.status, 500);
        assert_eq!(
            failed.content_type.as_deref(),
            Some("text/plain; charset=utf-8")
        );
        assert_eq!(failed.body, b"Internal Server Error");
        // Refusing, missing or malformed: the forwarded route's 502, never a partial answer.
        for (status, body) in [
            (
                503,
                r#"{"detail":"Native model manager owns this endpoint"}"#,
            ),
            (404, r#"{"detail":"Not Found"}"#),
            (200, r#"{"loaded":{}}"#),
            (200, r#"{"loaded":{},"fit":{}}"#),
        ] {
            let (base, _seen) = child(status, body.into()).await;
            let answer = send(state(Some((&models, &ini)), &base), "GET", uri, true).await;
            assert_eq!(answer.status, 502, "{status} {body}");
            assert_eq!(answer.body, UNAVAILABLE);
        }
        let down = send(
            state(Some((&models, &ini)), "http://127.0.0.1:9"),
            "GET",
            uri,
            true,
        )
        .await;
        assert_eq!(down.status, 502);
        assert_eq!(down.body, UNAVAILABLE);
        // A file part that fails is answered without asking the child at all.
        std::fs::write(models.join("a.gguf"), b"NOPE").unwrap();
        let bad = send(
            state(Some((&models, &ini)), "http://127.0.0.1:9"),
            "GET",
            uri,
            true,
        )
        .await;
        assert_eq!(bad.status, 422);
        assert_eq!(
            bad.body,
            br#"{"detail":"Could not read the model file: not a GGUF file (magic=b'NOPE')"}"#
        );
    }

    #[tokio::test]
    async fn a_link_leaving_the_models_folder_refuses() {
        let dir = tempfile::tempdir().unwrap();
        let models = folder(dir.path());
        std::fs::write(dir.path().join("outside.gguf"), hex(LLAMA)).unwrap();
        std::os::unix::fs::symlink(dir.path().join("outside.gguf"), models.join("b.gguf")).unwrap();
        let answer = send(
            state(
                Some((&models, &models.join("models.ini"))),
                "http://127.0.0.1:9",
            ),
            "GET",
            "/api/v1/models/detail?key=a.gguf",
            true,
        )
        .await;
        assert_eq!(answer.status, 503);
        assert_eq!(answer.body, REFUSED);
    }
}
